import re
s=open('Arbeitsblatt_fx991_Ableitung.html').read()
def rep(a,b):
    global s
    assert s.count(a)==1,a[:60]; s=s.replace(a,b)
rep('<title>Ableitung fx-991DE CW</title>','<title>Ableitung fx-991DE X</title>')
rep('<div class="sub">Ableitung mit d/dx (CATALOG ▸ Funktionsanalyse) &middot; CASIO fx-991DE CW</div>','<div class="sub">Ableitung mit d/dx (SHIFT ∫) im Modus 1: Berechnungen &middot; CASIO fx-991DE X</div>')
a=s.index('<p class="an weg">'); b=s.index('</div><div class="qrs">')
s=s[:a]+'''<p class="an weg"><span class="taste">MENU</span> <span class="taste w">1</span> Berechnungen &nbsp;▸&nbsp; <span class="taste sh">SHIFT</span> <span class="taste">∫▭</span> (d/dx) &nbsp;▸&nbsp; Term eingeben &nbsp;▸&nbsp; <span class="taste">▶</span> &nbsp;▸&nbsp; Stelle eingeben <span class="taste w">=</span></p>
<p class="an tipp"><b class="t">Tipp:</b> <i>x</i>³ mit <span class="taste"><i>x</i></span> <span class="taste"><i>x</i><sup>■</sup></span> 3 <span class="taste">▶</span>. Vorzeichen mit <span class="taste">(−)</span>. Neue Stelle: <span class="taste">◀</span> <span class="taste b">DEL</span> Zahl <span class="taste w">=</span>. Bruch? <span class="taste">S⇔D</span>.</p>
'''+s[b:]
QR=''
a=s.index('<div class="qrs">'); b=s.index('</svg></a></div></div>')+len('</svg></a></div></div>')
keys=''.join(f'<rect x="{x}" y="{y}" width="3.4" height="2.1" rx="0.5" fill="{"#3d6fd1" if (y=="29.9" and x in ("18.0","22.7")) else "#f2f2f4"}"/>' for y in ("29.9","32.9") for x in ("3.9","8.6","13.3","18.0","22.7"))
s=s[:a]+('<div class="qrs"><a class="qrlink" href="https://olafkott.github.io/CAS/fx991/fx991DEX_Ableitung_Schritt_fuer_Schritt.html"><svg class="qrframe" viewBox="0 0 30 40" width="24mm" height="32mm" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink"><rect x="1.5" y="0.4" width="27" height="36" rx="3.6" fill="#e6e6ea"/><rect x="2.4" y="1.3" width="25.2" height="34.2" rx="3" fill="#1e1e21"/><text x="3.8" y="3.9" font-family="Arial,sans-serif" font-size="2.1" font-weight="bold" fill="#fff">CASIO</text><text x="26.2" y="3.9" text-anchor="end" font-family="Georgia,serif" font-style="italic" font-size="1.5" letter-spacing="0.3" fill="#d94b5a">CLASSWIZ</text><rect x="3.6" y="4.8" width="22.8" height="22.4" rx="0.8" fill="#d3ded4"/><rect x="4.4" y="5.4" width="21.2" height="21.2" fill="#fff"/>'
 f'<image x="5" y="6" width="20" height="20" href="data:image/png;base64,{QR}" xlink:href="data:image/png;base64,{QR}"/>'+keys+
 '<text x="15" y="39.4" text-anchor="middle" font-family="Georgia,serif" font-size="3.1" font-weight="bold" fill="#333">Schritt für Schritt</text></svg></a></div></div>')+s[b:]
rep('href="https://olafkott.github.io/CAS/fx991/Loesung_fx991_Ableitung.html"','href="https://olafkott.github.io/CAS/fx991/Loesung_fx991DEX_Ableitung.html"')
rep('href="https://olafkott.github.io/CAS/fx991/fx991_Uebung_Ableitung.html"','href="https://olafkott.github.io/CAS/fx991/fx991DEX_Uebung_Ableitung.html"')
imgs=re.findall(r'<img src="data:image/png;base64,([A-Za-z0-9+/=]+)" alt="QR-Code (Lösung|Übung)">',s); assert len(imgs)==2
NEW={'Lösung':'',
'Übung':''}
for old,k in imgs: s=s.replace(old,NEW[k])
open('Arbeitsblatt_fx991DEX_Ableitung.html','w').write(s); print('ok', len(s))
